parameters.functionScript:
var target = Inputs.target;
if (!target) { Outputs.missing(); return; }

var section = document.querySelector('.' + target);
if (!section) { Outputs.missing(); return; }

// The header sticks, so it covers the top of whatever we scroll to.
var header = document.querySelector('.site-header');
var headerHeight = header ? header.getBoundingClientRect().height : 0;
var top = section.getBoundingClientRect().top + window.scrollY - headerHeight;

var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
window.scrollTo({ top: Math.max(0, top), behavior: reduce ? 'auto' : 'smooth' });
Outputs.done();
